BASE=Path(__file__).resolve().parents[1]
E=html.escape
SOURCES['condorcet']=('Condorcet, Réflexions sur l’esclavage des Nègres, 1781 — UQAM','https://classiques.uqam.ca/classiques/condorcet/reflexions_esclavage_negres/reflexions_esclavage_negres.html')
