LESSONS[2]['sources'].append('condorcet'); LESSONS[8]['sources'].append('leone')
docdict={d['id']:d for d in DOCS}
def write(path,text):
 p=BASE/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def link(source):
 title,url=SOURCES[source];return f'<a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(title)}</a>'
def ul(items,cls=''):
 return f'<ul class="{cls}">'+''.join(f'<li>{E(x)}</li>' for x in items)+'</ul>'
def docs_card(did,root='',short=False):
 d=docdict[did]
 return f'''<article class="source-card card" id="fonte-{d['id']}"><p class="eyebrow">Fonte primaria · {d['date']}</p><h3>{E(d['title'])}</h3><p>{E(d['context'])}</p><blockquote lang="{d['lang']}">{E(d['quote'])}</blockquote><p class="translation"><strong>Traduzione redazionale:</strong> {E(d['translation'])}</p><p><strong>Che cosa osservare.</strong> {E(d['observe'])}</p><p class="source-ref">{link(d['source'])}</p></article>'''
def mapsvg(i,title,nodes):
 # Sei nodi in topologia 1 → 4 → 1, con descrizione testuale equivalente.
 def text(x,y,s,size=25,color='#fff4da',width=24):
  lines=textwrap.wrap(s,width=width)
  return ''.join(f'<text x="{x}" y="{y+j*(size+7)}" fill="{color}" text-anchor="middle" font-family="Georgia,serif" font-size="{size}">{E(l)}</text>' for j,l in enumerate(lines))
 def box(x,y,w,h,s,large=False):
  parts=s.split('|');return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="7" fill="{("#173c52" if large else "#f5e8cd")}" stroke="#d7b576" stroke-width="2"/>'+text(x+w/2,y+35,parts[0],24,'#f9e8c5' if large else '#172b38',35 if large else 21)+(text(x+w/2,y+100 if not large else y+78,parts[1],22,'#f9e8c5' if large else '#3e3b31',50 if large else 24) if len(parts)>1 else '')
 parts=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 820" role="img" aria-labelledby="title desc"><title id="title">{E(title)}</title><desc id="desc">{E(". ".join(nodes))}</desc><defs><marker id="a" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#d7b576"/></marker></defs><rect width="1100" height="820" fill="#061d2f"/><rect x="14" y="14" width="1072" height="792" rx="10" fill="none" stroke="#d7b576"/>',text(550,62,title,26,width=75)]
 parts.append(box(255,98,590,95,nodes[0],True))
 for x,y,n in [(65,280,nodes[1]),(585,280,nodes[2]),(65,460,nodes[3]),(585,460,nodes[4])]:
  route=f"M550 195 L550 230 L{x+225} 230 L{x+225} {y-7}" if y==280 else f"M{x+225} 427 L{x+225} {y-7}"
  parts.append(f'<path d="{route}" fill="none" stroke="#d7b576" stroke-width="2" marker-end="url(#a)"/>')
  parts.append(box(x,y,450,145,n))
 parts.append('<path d="M290 607 L290 630 L810 630 L810 607 M550 630 L550 651" fill="none" stroke="#d7b576" stroke-width="2" marker-end="url(#a)"/>')
 parts.append(box(115,658,870,138,nodes[5],True));parts.append('</svg>')
 write(f'assets/mappe/{i:02}.svg',''.join(parts))
def mapbutton(i,title,root=''):
 return f'<button class="map-thumb" type="button" data-open-map data-map-src="{root}assets/mappe/{i:02}.svg" data-map-title="{E(title)}"><img src="{root}assets/mappe/{i:02}.svg" alt="Mappa: {E(title)}" loading="lazy"><span>Apri mappa a tutta pagina ⛶</span></button>'
def quiz(q,i,root=''):
 prompt,options,answer,reason=q
 return f'<fieldset data-answer="{answer}"><legend>{E(prompt)}</legend>'+''.join(f'<label><input type="radio" name="q{i}" value="{j}"><span>{E(o)}</span></label>' for j,o in enumerate(options))+f'<div class="feedback" hidden><strong class="feedback-prefix"></strong>{E(reason)} <a href="{root}lezioni/{LESSONS[i-1]["slug"]}.html#spiegazione">Riprendi la lezione {i}</a>.</div></fieldset>'
def notebook(key,label='Taccuino',id='notes'):
 return f'<section class="panel notebook"><h2>{label}</h2><label for="{id}">Appunti personali</label><textarea id="{id}" data-note="{key}" spellcheck="true" placeholder="Scrivi domande, nessi e passaggi da ricordare…"></textarea><p class="status" role="status" data-save-status>Appunti conservati solo su questo dispositivo.</p><div class="actions"><button data-download-note="{id}">Scarica .txt</button><button data-clear-note="{id}">Cancella appunti</button></div></section>'
def shell(title,body,path,root='',page='tools',lesson='',cover=False):
 shared=root+'../../pwa-common/'
 nav=''.join(f'<a href="{root}{url}"'+(' aria-current="page"' if path==url else '')+f'>{name}</a>' for name,url in [('Home','index.html'),('Percorso','percorso.html'),('Testi','documenti.html'),('Mappe','mappe.html'),('Protagonisti','protagonisti.html')])
 header='' if cover else f'<header class="topbar"><a class="brand" href="{root}index.html"><span class="seal" aria-hidden="true">SL</span>Schiavitù e libertà</a><nav aria-label="Navigazione principale">{nav}</nav></header>'
 if lesson: header+='<div class="mobile-panels" aria-label="Pannelli della lezione"><button data-panel-button="read" aria-pressed="true">Leggi</button><button data-panel-button="visual" aria-pressed="false">Osserva</button><button data-panel-button="notes" aria-pressed="false">Appunti</button></div>'
 modal=f'''<dialog id="map-dialog" class="map-dialog" aria-labelledby="map-title"><header><strong id="map-title">Mappa</strong><div class="actions"><button data-zoom="-.25" aria-label="Riduci mappa">−</button><button data-zoom=".25" aria-label="Ingrandisci mappa">+</button><button data-fullscreen>Schermo intero</button><button data-close-map autofocus>Chiudi</button></div></header><p class="small">Usa + e − per lo zoom. Premi Esc o Chiudi per tornare alla pagina.</p><div class="map-stage"><img alt="" src="{root}assets/mappe/01.svg"></div></dialog>'''
