svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 820" role="img" aria-labelledby="t d"><title id="t">Il meccanismo dell’esclusione</title><desc id="d">Interesse, giustificazione, normalizzazione, esclusione, resistenza, cambiamento. Una chiave di analisi, non una legge automatica.</desc><defs><marker id="a" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3z" fill="#dab572"/></marker></defs><rect width="1100" height="820" fill="#061d2f"/><text x="550" y="72" text-anchor="middle" fill="#fff4da" font-family="Georgia" font-size="34">Il meccanismo dell’esclusione</text>'
