test='<p>La verifica alterna comprensione, confronto e uso delle fonti. Le risposte aperte hanno criteri di autovalutazione; non ricevono un voto automatico.</p><h2>1. Comprendere i processi</h2><form data-quiz id="quiz-finale">'+''.join(quiz(l['quiz'],i) for i,l in enumerate(LESSONS,1))+'<button type="submit">Correggi le dieci risposte</button> <button type="button" data-reset-quiz>Ricomincia</button><p class="quiz-result" data-quiz-result tabindex="-1" role="status" hidden></p></form>'
test+='<h2>2. Vero o falso ragionato</h2><form data-quiz id="vero-falso"><fieldset data-answer="falso"><legend>La legge britannica del 1807 rese libere tutte le persone schiavizzate nelle colonie.</legend><label><input type="radio" name="vf" value="vero">Vero</label><label><input type="radio" name="vf" value="falso">Falso</label><label for="ragione-vf">Spiega la tua scelta</label><textarea id="ragione-vf" data-note="vf" rows="3" style="width:100%"></textarea><p data-save-status role="status"></p><div class="feedback" hidden><strong class="feedback-prefix"></strong>Il 1807 riguarda la tratta. La legge sulla schiavitù è del 1833, applicata dal 1834 con apprenticeship fino al 1838 nelle Indie occidentali britanniche. <a href="lezioni/09-abolizione.html">Recupero</a>.</div></fieldset><button>Controlla</button></form>'
test+='<h2>3. Associa autore e strategia</h2>'
for person,ans,why in [('Equiano','Autobiografia','Racconta la propria esperienza e sostiene la campagna contro la tratta.'),('Prince Hall','Petizione','L’azione è collettiva e rivolta alle istituzioni.'),('Stringfellow','Autorità religiosa','Usa la Scrittura per sostenere una tesi pro-schiavitù.')]:
 test+=f'<div class="card"><label>{person}: <select data-classify="{ans}" data-explain="{E(why)}"><option value="">Scegli</option><option>Petizione</option><option>Autobiografia</option><option>Autorità religiosa</option></select></label><p class="feedback" role="status" hidden></p></div>'
test+='<h2>4. Metti in ordine</h2><p>Assegna i numeri da 1 (prima) a 4 (ultima).</p><div class="cards">'+''.join(f'<label class="card">{name} <input type="number" min="1" max="4" data-order aria-label="Ordine: {name}"></label>' for name in ['Abolizione francese del 1794','Applicazione britannica del 1834','Divieto britannico della tratta del 1807','XIII Emendamento del 1865'])+'</div><p><button data-check-order>Verifica la cronologia</button></p><p id="order-feedback" class="feedback" role="status"></p>'
test+='<h2>5. Analizza una fonte</h2>'+docs_card('douglass')+'<p>Spiega in 80–120 parole il valore di «your», la data del discorso e la contraddizione resa visibile.</p>'+notebook('analisi-fonte','La tua analisi','analisi')+'<details><summary>Criteri di autovalutazione</summary><ul><li>Ho identificato Rochester e il 5 luglio 1852.</li><li>Ho distinto chi celebra da chi è escluso.</li><li>Ho collegato la fonte alla Dichiarazione del 1776.</li><li>Ho usato il testo, senza inventare parole di Douglass.</li></ul></details><h2>6. Riconosci gli argomenti</h2><p><a class="btn" href="confronto.html">Apri il confronto delle tesi</a></p>'
page('Test di verifica','Dall’informazione ricordata al ragionamento storico.',test,'test.html')

