maphtml='''<p class="question">Una rete di rotte, non un solo triangolo.</p><p>Carta schematica dell’Atlantico: coste semplificate, nessuna pretesa di ricostruire confini in un singolo anno. Le frecce non sono proporzionali ai flussi.</p><svg class="route-map" viewBox="0 0 1000 620" role="img" aria-labelledby="carta-title carta-desc"><title id="carta-title">Rotte della tratta atlantica</title><desc id="carta-desc">Africa a destra, Americhe a sinistra, Europa in alto a destra. Rotte verso Brasile, Caraibi e America settentrionale; flussi di merci verso Europa e Africa. I pulsanti sotto forniscono descrizioni equivalenti.</desc><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3z" fill="#f5cd77"/></marker></defs><path class="sea-line" d="M0 120H1000 M0 240H1000 M0 360H1000 M0 480H1000 M200 0V620 M400 0V620 M600 0V620 M800 0V620"/><path class="land" d="M0 10L350 10 333 53 300 63 300 97 266 119 237 160 226 205 203 226 198 260 221 287 250 300 244 314 215 300 183 271 147 250 120 217 105 170 73 153 53 92 0 90Z"/><path class="land" d="M245 326L279 317 313 333 350 345 377 372 380 408 353 441 343 477 321 512 304 563 280 590 271 554 255 520 250 475 230 433 215 390 220 355Z"/><path class="land" d="M667 195L710 162 785 159 833 184 848 214 871 239 852 282 825 316 824 368 799 417 775 454 753 432 742 397 726 354 703 323 667 313 647 279 643 236Z"/><path class="land" d="M712 154L689 140 691 118 720 109 731 76 758 52 784 45 799 16 1000 5 1000 184 894 189 853 165 828 170 796 141 766 149 737 132Z"/><path class="land" d="M697 75L704 80 701 111 689 115 683 105Z M671 83L680 87 677 108 668 107Z M251 268L284 271 299 281 279 283 250 276Z M304 293L329 296 340 305 308 307Z M338 319L349 325 345 335Z"/><text x="70" y="110" font-size="26">AMERICA SETTENTRIONALE</text><text x="205" y="245" font-size="23">Caraibi</text><text x="285" y="399" font-size="28">Brasile</text><text x="732" y="271" font-size="34">AFRICA</text><text x="780" y="106" font-size="28">EUROPA</text><text x="435" y="302" font-size="27" opacity=".8">ATLANTICO</text><text x="260" y="350" font-size="17">AMERICA</text><text x="257" y="373" font-size="17">MERIDIONALE</text><path class="route" data-route="brazil" d="M732 345Q550 475 374 392"/><path class="route" data-route="caribbean" d="M653 251Q500 160 323 287"/><path class="route" data-route="north" d="M657 227Q477 70 243 179"/><path class="route goods" data-route="goods" d="M314 267Q493 15 692 89"/><path class="route goods" data-route="goods" d="M718 130Q790 180 688 245"/><text x="430" y="556" font-size="21">Linea continua: deportazione di persone</text><text x="430" y="588" font-size="21">Linea tratteggiata: merci e circuiti commerciali</text></svg><div class="timeline-tools" aria-label="Esplora aree e flussi"><button data-route-button="africa" aria-pressed="true">Africa</button><button data-route-button="brazil" aria-pressed="false">Brasile</button><button data-route-button="caribbean" aria-pressed="false">Caraibi</button><button data-route-button="north" aria-pressed="false">America settentrionale</button><button data-route-button="goods" aria-pressed="false">Merci e scambi</button></div><section class="route-panel" aria-live="polite"><h2 id="route-title">Africa: molte società, molte traiettorie</h2><p id="route-description">Africa occidentale e centro-occidentale sono aree centrali d’imbarco. Le rotte cambiano nel tempo; esplora le destinazioni e i flussi con i pulsanti.</p></section>'''
maphtml+='<h2>Ordini di grandezza, non pseudo-precisione</h2><div class="data-row"><div><strong>≈ 12,5 milioni</strong>persone imbarcate in Africa</div><div><strong>≈ 10,7 milioni</strong>persone sbarcate vive</div><div><strong>≈ 1,8 milioni</strong>differenza fra le due stime</div></div><p><strong>Stime arrotondate, periodo 1501–1866.</strong> La differenza misura l’ordine di grandezza dei decessi nella traversata; non tutte le vittime prima della partenza o dopo l’arrivo. L’aggiornamento degli archivi può modificare le stime.</p><p class="source-ref">'+link('tratta')+' · '+link('neh')+'</p><h2>Le principali aree coloniali</h2><div class="table-wrap"><table><tr><th>Area</th><th>Collegamenti da ricordare</th></tr><tr><td>Brasile</td><td>Portogallo, poi Brasile indipendente; intensi circuiti diretti sud-atlantici.</td></tr><tr><td>Caraibi</td><td>Saint-Domingue francese; Giamaica e Barbados britanniche; Cuba spagnola; colonie olandesi e danesi.</td></tr><tr><td>America settentrionale</td><td>Colonie britanniche, poi Stati Uniti; traffici diretti e redistribuzioni interne.</td></tr><tr><td>Europa</td><td>Porti, manufatti, credito e consumo di prodotti coloniali.</td></tr></table></div><p><a href="timeline.html">Colloca i divieti della tratta nel tempo →</a></p>'
page('Carte e dati','Attraversare l’Atlantico dal punto di vista delle persone deportate.',maphtml,'carte.html')

bib='<h2>Fonti primarie e risorse di controllo</h2><p>Consultazione editoriale: 9 settembre 2026. I link aprono risorse esterne. Gli estratti locali restano disponibili offline. Alcuni archivi possono richiedere più tempo o limitare l’accesso automatico.</p><ol class="source-links">'+''.join('<li id="src-'+k+'">'+link(k)+'</li>' for k in SOURCES)+'</ol><h2>Come sono state lette le fonti</h2><ul><li>Distinzione fra Dichiarazione del 1776 e Costituzione del 1787.</li><li>Confronto fra testo delle norme e loro applicazione territoriale.</li><li>Citazioni brevi; traduzioni redazionali esplicitamente indicate.</li><li>Sojourner Truth: trascrizione Robinson 1851 distinta dalla rielaborazione Gage 1863.</li><li>Douglass: data del 5 luglio 1852 verificata sullo Smithsonian; il sommario del National Constitution Center riporta impropriamente giugno.</li><li>Equiano: l’autobiografia non viene trattata come documento privo di mediazioni.</li><li>Dati contemporanei etichettati con anno del dato e anno del rapporto.</li></ul><h2>Crediti dei materiali</h2><p>Copertina fornita da gbprof, conservata senza modifiche. Le immagini della copertina sono illustrazioni, non riproduzioni di documenti da usare come prove. Mappe SVG e carta schematica: elaborazione didattica gbprof e Libera.</p><p>I quindici ritratti documentari riportano fonte e attribuzione nella pagina Protagonisti; sono ridimensionati e compressi per l’uso offline, senza ricostruire i volti. I ritratti, anche postumi, sono distinti dalle fotografie e non vanno automaticamente considerati rappresentazioni dal vivo.</p>'
page('Bibliografia e sitografia','Fonti consultabili, metodo e crediti dei materiali.',bib,'bibliografia.html')
privacy='''<h2>Privacy dei materiali</h2><p>Questa PWA non contiene pubblicità, analytics, tracker o cookie di profilazione. Non richiede account, nomi, email o invio delle risposte a un server. Appunti, risultati e progressi rimangono nel localStorage del browser su questo dispositivo e su questo dominio.</p><p>Gli appunti non vengono sincronizzati fra dispositivi. In navigazione privata, con memoria piena o dopo la cancellazione dei dati del browser possono andare persi. Usa Scarica .txt per conservarne una copia. Le evidenziature durano per la lettura corrente.</p><p>Il sito che ospita le pagine riceve le normali richieste di rete necessarie alla navigazione. I link alle fonti esterne vengono aperti solo quando li scegli; valgono allora le condizioni dei rispettivi siti. Non vengono caricati font, video o immagini da servizi esterni.</p><button data-clear-all>Cancella tutti i dati locali di questa PWA</button><h2>Accessibilità</h2><p>Indice testuale equivalente alla copertina, skip link, navigazione da tastiera, focus visibile, etichette, testi alternativi e messaggi di stato. Le mappe hanno descrizioni e spiegazioni nelle lezioni. Puoi ingrandire il testo e usare Focus / LIM; sui dispositivi piccoli i pannelli Leggi, Osserva e Appunti consentono di cambiare area.</p><p>Le impostazioni di riduzione del movimento sono rispettate. Ogni esito di una verifica è espresso anche a parole. Per chi usa uno screen reader è preferibile l’indice testuale: i piccoli testi disegnati nella copertina non possono essere ingranditi separatamente.</p><h2>Offline e installazione</h2><p>Dopo il primo caricamento completato, le pagine, la copertina, gli estratti, le mappe, i quiz e i ritratti locali vengono conservati nella cache della PWA. Le pagine integrali degli archivi esterni richiedono Internet. Attendi l’indicazione di disponibilità offline prima di scollegarti.</p><p>Il service worker opera solo in questa cartella e sulle due risorse condivise di accessibilità esplicitamente necessarie. Gli aggiornamenti usano una cache distinta: il pulsante Aggiorna la PWA attiva una versione già scaricata. In alternativa chiudi tutte le schede della PWA e riaprila.</p>'''+install
page('Privacy e accessibilità','Studiare senza inviare appunti o risultati personali.',privacy,'privacy-accessibilita.html')
page('Sei offline','Questa pagina non è disponibile nella copia salvata.', '<p>Torna ai materiali principali già memorizzati. Gli archivi esterni richiedono una connessione.</p><p><a class="btn" href="index.html">Torna alla copertina</a> <a class="btn" href="percorso.html">Apri le lezioni</a></p>','offline.html')

write('assets/icone/icon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#061d2f"/><circle cx="256" cy="256" r="185" fill="none" stroke="#dab572" stroke-width="8"/><path d="M130 330V188Q188 164 256 192Q324 164 382 188V330Q317 309 256 339Q194 309 130 330Z M256 192V339" fill="none" stroke="#dab572" stroke-width="12"/><path d="M244 94L244 153 M269 94L269 153" stroke="#fff5dc" stroke-width="10"/></svg>')
manifest=dict(id='./',name='Schiavitù e libertà — gbprof',short_name='Schiavitù e libertà',lang='it',description='Dieci lezioni di storia, documenti, mappe e strumenti di studio.',start_url='./index.html',scope='./',display='standalone',orientation='any',background_color='#061d2f',theme_color='#061d2f',icons=[dict(src=f'assets/icone/icon-{s}.png',sizes=f'{s}x{s}',type='image/png',purpose='any maskable') for s in [192,512]])
write('manifest.json',json.dumps(manifest,ensure_ascii=False,indent=2))
write('assets/dati/fonti.json',json.dumps(SOURCES,ensure_ascii=False,indent=2))
write('assets/dati/timeline.json',json.dumps(EVENTS,ensure_ascii=False,indent=2))
# Inventario locale chiuso: nessuna cache di pagine esterne o di altre PWA.
files=sorted(str(p.relative_to(BASE)) for p in BASE.rglob('*') if p.is_file() and p.suffix in ['.html','.css','.js','.svg','.png','.PNG','.jpg','.webp','.json'] and not any(x in p.parts for x in ['tools','node_modules']) and p.name!='service-worker.js')
files+=['assets/icone/icon-192.png','assets/icone/icon-512.png']
files=sorted(set(files));shared=['../../pwa-common/gbprof-accessibility.css','../../pwa-common/gbprof-accessibility.js']
digest=hashlib.sha256(b''.join((BASE/p).read_bytes() for p in files if (BASE/p).exists())).hexdigest()[:12]
sw='''const PREFIX='schiavitu-liberta-';
const CACHE=PREFIX+'VERSION';
const LOCAL=FILES;
const SHARED=SHARED_LIST;
const BASE=new URL('./',self.location.href);
const ALLOWED=new Set([...LOCAL,...SHARED].map(p=>new URL(p,BASE).href));
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);await c.addAll([...LOCAL,...SHARED].map(p=>new Request(new URL(p,BASE),{cache:'reload'})));})()));
self.addEventListener('message',e=>{if(e.data?.type==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil((async()=>{const names=await caches.keys();await Promise.all(names.filter(n=>n.startsWith(PREFIX)&&n!==CACHE).map(n=>caches.delete(n)));await self.clients.claim();})()));
self.addEventListener('fetch',e=>{
 if(e.request.method!=='GET')return;
 const u=new URL(e.request.url);if(u.origin!==BASE.origin)return;
 const inScope=u.pathname.startsWith(BASE.pathname);u.search='';u.hash='';
 if(!inScope&&!ALLOWED.has(u.href))return;
 if(u.pathname===BASE.pathname)u.pathname+='index.html';
 e.respondWith((async()=>{
  const c=await caches.open(CACHE);const hit=await c.match(u.href);
  // Ogni versione è una copia coerente; nuove versioni passano da install/activate.
  if(hit)return hit;
  try{return await fetch(e.request);}catch{
   if(e.request.mode==='navigate')return (await c.match(new URL('offline.html',BASE).href))||Response.error();
   return Response.error();
  }
 })());
});
'''.replace('VERSION',digest).replace('FILES',json.dumps(files,ensure_ascii=False)).replace('SHARED_LIST',json.dumps(shared))
write('service-worker.js',sw)
print(f'Generate {len(list(BASE.glob("*.html")))} pagine strumenti/home, 10 lezioni, 12 mappe. Cache {digest}: {len(files)+len(shared)} risorse.')
